  /// Builds a presentation of the held credential [credentialId] in answer
  /// to [request], ready to send to the requester: the credential as issued,
  /// the disclosures the request's DCQL query names and nothing else, bound
  /// to the request's nonce and domain and signed by the holder key
  /// (`Ed25519Signature2020` over the RFC 8785 form without `proof`).
  ///
  /// The credential stays in the wallet; it can be presented again.
  Future<Map<String, dynamic>> createPresentation(
    String credentialId,
    PresentationRequest request,
  ) async {
    final credential = _store.byId(credentialId);
    if (credential == null) {
      throw WalletException('No credential $credentialId');
    }
    final key = _store.holderKey;
    if (key == null || key.did != credential.holderDid) {
      throw WalletException(
        'Credential $credentialId is not held by this wallet\'s key',
      );
    }
    final expiresAt = credential.vc['expires_at'];
    if (expiresAt is! int) {
      throw WalletException('Credential $credentialId has no expires_at');
    }
    final now = _clock().millisecondsSinceEpoch ~/ 1000;
    if (now > expiresAt) {
      throw WalletException('Credential $credentialId has expired');
    }

    final presentation = <String, dynamic>{
      '@context': ['https://www.w3.org/2018/credentials/v1'],
      'type': ['VerifiablePresentation'],
      'holder': key.did,
      'verifiableCredential': credential.vc,
      'disclosures': [
        for (final disclosure in _requested(credential, request.dcqlQuery))
          disclosure.toJson(),
      ],
      'nonce': request.nonce,
      'domain': request.domain,
    };
    final signature = await key.sign(
      utf8.encode(JcsUtil.canonicalize(presentation)),
    );
    presentation['proof'] = {
      'type': 'Ed25519Signature2020',
      'created': now,
      'verificationMethod': key.keyId,
      'proofPurpose': 'authentication',
      'proofValue': toMultiBase(signature),
    };
    return presentation;
  }

  /// The disclosures of [credential] that [query] names: a claim path
  /// `credentialSubject.<name>` is the disclosure called `<name>`. Any other
  /// kind of query is refused rather than guessed at.
  List<Disclosure> _requested(
    HeldCredential credential,
    DcqlCredentialQuery query,
  ) {
    if (query.credentialSets != null || query.credentials.length != 1) {
      throw const WalletException('Only a query for one credential is supported');
    }
    final wanted = query.credentials.single;
    if (wanted.format != CredentialFormat.ldpVc || wanted.claimSets != null) {
      throw WalletException('Unsupported credential query ${wanted.id}');
    }
    final names = <String>{};
    for (final claim in wanted.claims ?? const <DcqlClaim>[]) {
      final path = claim.path;
      if (claim.values != null ||
          path.length != 2 ||
          path[0] != 'credentialSubject' ||
          path[1] is! String) {
        throw WalletException('Unsupported claim request $path');
      }
      names.add(path[1] as String);
    }
    return [
      for (final name in names)
        credential.disclosures.firstWhere(
          (disclosure) => disclosure.name == name,
          orElse: () => throw WalletException(
            'Credential ${credential.id} has no claim $name',
          ),
        ),
    ];
  }
}

