// Builds presentations with the real WalletService from the real backend
// issuance, for the backend verifier to check.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:credentials_app/src/credential_store.dart';
import 'package:credentials_app/src/held_credential.dart';
import 'package:credentials_app/src/holder_key.dart';
import 'package:credentials_app/src/issuer_client.dart';
import 'package:credentials_app/src/presentation_request.dart';
import 'package:credentials_app/src/wallet_service.dart';

class NoIssuer implements IssuerClient {
  @override
  Future<HeldCredential> issue({required String holderDid, required String credentialType}) => throw UnimplementedError();
}

PresentationRequest door(String nonce) => PresentationRequest.fromJson({
  'client_id': 'door-scanner.members.test',
  'nonce': nonce,
  'dcql_query': {'credentials': [{'id': 'membership', 'format': 'ldp_vc', 'claims': [{'path': ['credentialSubject', 'member']}]}]},
});

Future<void> main(List<String> args) async {
  final issuance = jsonDecode(File(args[0]).readAsStringSync()) as Map<String, dynamic>;
  final store = CredentialStore()
    ..holderKey = HolderKey.fromSeed(Uint8List.fromList(List.filled(32, 7)))
    ..save(HeldCredential.fromIssuance(issuance));
  final id = (issuance['credential'] as Map)['id'] as String;
  final wallet = WalletService(issuer: NoIssuer(), store: store,
      clock: () => DateTime.fromMillisecondsSinceEpoch(1780272000 * 1000, isUtc: true));
  final out = {
    'visit-1': await wallet.createPresentation(id, door('n-visit-1')),
    'visit-2': await wallet.createPresentation(id, door('n-visit-2')),
  };
  File(args[1]).writeAsStringSync(jsonEncode(out));
  print('wallet wrote ${out.length} presentations; still holds ${wallet.heldCredentials().length} credential(s)');
}
